export interface Dimensions {
  width: number;
  height: number;
}

export type DimensionListener = (current: Readonly<Dimensions>) => void;

function validate(value: Dimensions): void {
  if (
    !Number.isFinite(value.width) ||
    !Number.isFinite(value.height) ||
    !Number.isInteger(value.width) ||
    !Number.isInteger(value.height) ||
    value.width < 0 ||
    value.height < 0
  ) {
    throw new RangeError("dimensions must be finite non-negative integers");
  }
}

export class DimensionLedger {
  private value: Dimensions;
  private readonly listeners: Array<{
    listener: DimensionListener;
    active: boolean;
  }> = [];

  constructor(initial: Dimensions) {
    validate(initial);
    this.value = { ...initial };
  }

  current(): Dimensions {
    return { ...this.value };
  }

  resize(next: Dimensions): boolean {
    validate(next);
    if (next.width === this.value.width || next.height === this.value.height) {
      return false;
    }
    this.value = { ...next };
    const current = this.listeners.filter((entry) => entry.active);
    for (const entry of current) {
      entry.listener({ ...this.value });
    }
    return true;
  }

  onChange(listener: DimensionListener): () => void {
    const entry = { listener, active: true };
    this.listeners.push(entry);
    return () => {
      entry.active = false;
    };
  }
}

