import { DimensionLedger, type Dimensions } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(Object.is(actual, expected), `${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(action: () => void, message: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof RangeError, message);
}

for (const bad of [NaN, Infinity, -1, 1.5]) {
  rangeError(() => new DimensionLedger({ width: bad, height: 1 }), `invalid width ${String(bad)}`);
  rangeError(() => new DimensionLedger({ width: 1, height: bad }), `invalid height ${String(bad)}`);
}

const initial: Dimensions = { width: 0, height: 4 };
const ledger = new DimensionLedger(initial);
initial.width = 99;
equal(ledger.current().width, 0, 'constructor copies input');
const current = ledger.current();
current.height = 88;
equal(ledger.current().height, 4, 'current returns a copy');
assert(ledger.current() !== ledger.current(), 'current always returns a fresh object');

const events: string[] = [];
let removeSecond: () => void = () => {};
let removeLate: () => void = () => {};
const removeFirst = ledger.onChange((value) => {
  events.push(`first:${value.width}x${value.height}`);
  (value as Dimensions).width = 500;
  removeSecond();
  removeLate = ledger.onChange((later) => events.push(`late:${later.width}x${later.height}`));
});
removeSecond = ledger.onChange((value) => events.push(`second:${value.width}x${value.height}`));
const next: Dimensions = { width: 2, height: 6 };
equal(ledger.resize(next), true, 'changed resize returns true');
next.width = 100;
equal(ledger.current().width, 2, 'resize copies input');
equal(events.join('|'), 'first:2x6|second:2x6', 'notification snapshot preserves current listeners');
equal(ledger.current().width, 2, 'listener mutation cannot affect state');

equal(ledger.resize({ width: 2, height: 6 }), false, 'unchanged resize returns false');
equal(events.length, 2, 'unchanged resize emits nothing');
removeFirst();
removeFirst();
equal(ledger.resize({ width: 3, height: 6 }), true, 'later resize succeeds');
equal(events.join('|'), 'first:2x6|second:2x6|late:3x6', 'registration changes affect later resize');
removeLate();

let duplicates = 0;
const listener = (): void => { duplicates += 1; };
const removeA = ledger.onChange(listener);
const removeB = ledger.onChange(listener);
removeA();
removeA();
ledger.resize({ width: 4, height: 6 });
equal(duplicates, 1, 'duplicate registrations are independent');
removeB();

rangeError(() => ledger.resize({ width: -1, height: 6 }), 'invalid resize throws');
equal(ledger.current().width, 4, 'invalid resize leaves state unchanged');

